costs = {r[0]: r[1] for r in cells('Leaf costs', 'E30:F32')}

def expand(part):
    children = [r for r in rules if r[0] == part]
    if not children:
        return {part: 1}
    res = {}
    for p, comp, mult in children:
        sub = expand(comp)
        for k, v in sub.items():
            res[k] = res.get(k, 0) + v * mult
    return res

